"""Git hook installation and management."""

import stat
from pathlib import Path

from git import Repo

HOOK_TEMPLATE = """#!/bin/sh
# AI Git Hooks - {hook_name}
# Generated by ai-git-hooks v0.1.0

# Check if ai-git-hooks is installed
if ! command -v aigh >/dev/null 2>&1; then
    echo "Warning: ai-git-hooks not found in PATH"
    exit 0
fi

# Run the appropriate hook handler
exec aigh run-hook {hook_name} "$@"
"""

HOOK_NAMES = [
    "pre-commit",
    "prepare-commit-msg",
    "commit-msg",
    "post-checkout",
    "pre-push",
]


def get_git_dir() -> Path:
    """Get the git directory for the current repository."""
    try:
        repo = Repo(search_parent_directories=True)
        return Path(repo.git_dir)
    except Exception:
        raise RuntimeError("Not a git repository (or any of the parent directories)")


def install_hooks(hooks: list[str], force: bool = False) -> None:
    """Install AI Git Hooks into the current repository."""
    git_dir = get_git_dir()
    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    
    if "all" in hooks:
        hooks = [h for h in HOOK_NAMES if h != "all"]
    
    for hook_name in hooks:
        hook_path = hooks_dir / hook_name
        
        # Check if hook already exists
        if hook_path.exists() and not force:
            # Check if it's our hook
            with open(hook_path) as f:
                content = f.read()
                if "AI Git Hooks" in content:
                    # Our hook, safe to update
                    pass
                else:
                    # Existing hook, backup
                    backup_path = hook_path.with_suffix(".backup")
                    hook_path.rename(backup_path)
                    print(f"Backed up existing {hook_name} to {backup_path.name}")
        
        # Write hook
        hook_content = HOOK_TEMPLATE.format(hook_name=hook_name)
        with open(hook_path, "w") as f:
            f.write(hook_content)
        
        # Make executable
        hook_path.chmod(hook_path.stat().st_mode | stat.S_IEXEC)
        print(f"Installed {hook_name} hook")


def uninstall_hooks() -> None:
    """Remove AI Git Hooks from the current repository."""
    git_dir = get_git_dir()
    hooks_dir = git_dir / "hooks"
    
    for hook_name in HOOK_NAMES:
        hook_path = hooks_dir / hook_name
        if hook_path.exists():
            with open(hook_path) as f:
                content = f.read()
                if "AI Git Hooks" in content:
                    hook_path.unlink()
                    print(f"Removed {hook_name} hook")
                    
                    # Restore backup if exists
                    backup_path = hook_path.with_suffix(".backup")
                    if backup_path.exists():
                        backup_path.rename(hook_path)
                        print(f"Restored {hook_name} from backup")
